Running test case: tests/develop_test/01backpack.sysy
int max(int a, int b) {
    if (a > b)
        return a;
    else
        return b;
}

int main() {
    int w[4] = {2, 3, 4, 7};
    int c[4] = {1, 3, 5, 9};
    int f[5][11] = {0};
    int n = 4, m = 10;
    int i = 0;
    while (i < n) {
        int v = 1;
        while (v <= m) {
            if (v >= w[i]) {
                f[i + 1][v] = max(f[i][v - w[i]] + c[i], f[i][v]);
            }
            else {
                f[i + 1][v] = f[i][v];
            }
            v = v + 1;
        }
        i = i + 1;
    }
    return f[n][m];
}
Running test case: tests/develop_test/matmul.sysy
int ROWS_A = 2;
int COLS_A = 3;
int ROWS_B = 3;
int COLS_B = 2;

void matrix_multiply(int a[2][3], int b[3][2], int result[2][2]) {
    for (int i = 0; i < ROWS_A; i = i + 1) {
        for (int j = 0; j < COLS_B; j = j + 1) {
            result[i][j] = 0;
            for (int k = 0; k < COLS_A; k = k + 1) {
                result[i][j] = result[i][j] + a[i][k] * b[k][j];
            }
        }
    }
}

int main() {
    int matrix_a[2][3] = {{1, 2, 3}, {4, 5, 6}};
    int matrix_b[3][2] = {{7, 8}, {9, 10}, {11, 12}};
    int result[2][2];
    matrix_multiply(matrix_a, matrix_b, result);
    return result[1][1];
}
Running test case: tests/develop_test/quicksort.sysy
void swap(int arr[6], int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

int b(int arr[6], int low, int high) {
    int pivot = arr[high];
    int i = low - 1;
    for (int j = low; j < high; j = j + 1) {
        if (arr[j] <= pivot) {
            i = i + 1;
            swap(arr, i, j);
        }
    }
    swap(arr, i + 1, high);
    return i + 1;
}

int main() {
    int arr[6] = {10, 7, 8, 9, 1, 5};
    int n = 6;
    b(arr, 0, n - 1);
    return arr[5];
}
