Running test case: tests/develop_test/mergearray.sysy
int combine(int arr1[2], int arr1_length, int arr2[3], int arr2_length) {
    int sort_arr[5];
    int i = 0;
    int j = 0;
    int k = 0;
    while (i < arr1_length && j < arr2_length) {
        if (arr1[i] < arr2[j]) {
            sort_arr[k] = arr1[i];
            i = i + 1;
        }
        else {
            sort_arr[k] = arr2[j];
            j = j + 1;
        }
        k = k + 1;
    }
    if (i == arr1_length) {
        while (j < arr2_length) {
            sort_arr[k] = arr2[j];
            k = k + 1;
            j = j + 1;
        }
    }
    else {
        while (i < arr1_length) {
            sort_arr[k] = arr2[i];
            k = k + 1;
            i = i + 1;
        }
    }
    return sort_arr[arr1_length + arr2_length - 1];
}

int main() {
    int a[2] = {1, 5};
    int b[3][3] = {1, 4, 14, 1, 4, 14, 1, 4, 14};
    return combine(a, 2, b[1], 3);
}
Running test case: tests/develop_test/func_call_test.sysy
void swap(int arr[6], int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

int partition(int arr[6], int low, int high) {
    int pivot = arr[high];
    int i = low - 1;
    for (int j = low; j < high; j = j + 1) {
        if (arr[j] <= pivot) {
            i = i + 1;
            swap(arr, i, j);
        }
    }
    swap(arr, i + 1, high);
    return i + 1;
}

void quickSort(int arr[6], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

int main() {
    int arr[6] = {10, 7, 8, 9, 1, 5};
    int n = 6;
    quickSort(arr, 0, n - 1);
    return arr[5];
}
